#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Create a string stream to store the HTML content
    std::stringstream htmlStream;

    // Write the markdown content to the string stream
    htmlStream << markdown;

    // Return the HTML content as a string
    return htmlStream.str();
}

int main() {
    std::string markdown = "This is a markdown text";
    std::string html = markdownToHtml(markdown);
    std::cout << "Markdown: " << markdown << std::endl;
    std::cout << "HTML: " << html << std::endl;
    return 0;
}
```

